import { encodeLogicEnvelope, RealtimeInputGate } from '../dist/logic/index.js';

const fps = 240;
const durationMs = 10_000;
const frameMs = 1000 / fps;
const sampleCount = Math.round(durationMs / frameMs);
// Keep session isolation in the measured hot path. This is the same compact
// length generated by LogicClient, so transport regressions cannot hide the
// per-envelope reconnect metadata cost.
const sessionId = 's2x7m4k9q6v8n1';

const equals = (left, right) =>
  left.moveX === right.moveX
  && left.moveZ === right.moveZ
  && left.yaw === right.yaw
  && left.pitch === right.pitch
  && left.jumpHeld === right.jumpHeld
  && left.sprintHeld === right.sprintHeld
  && left.flyToggle === right.flyToggle;
const direction = (value) => value > 0.01 ? 1 : value < -0.01 ? -1 : 0;
const gate = new RealtimeInputGate({
  equals,
  merge: (pending, next) => ({ ...next, flyToggle: pending.flyToggle || next.flyToggle }),
  isUrgent: (previous, next) =>
    direction(previous.moveX) !== direction(next.moveX)
    || direction(previous.moveZ) !== direction(next.moveZ)
    || previous.jumpHeld !== next.jumpHeld
    || previous.sprintHeld !== next.sprintHeld
    || next.flyToggle,
  minimumIntervalMs: 1000 / 60,
  heartbeatMs: 250,
});

let baselineCharacters = 0;
let optimizedCharacters = 0;
let optimizedMessages = 0;
let flyToggleDelivered = 0;
let movementStartsDelivered = 0;
let movementStopsDelivered = 0;
let previousDeliveredMoveZ = 0;

for (let frame = 0; frame < sampleCount; frame++) {
  const at = frame * frameMs;
  const moving = at >= 1000 && at < 2000;
  const looking = at >= 3000 && at < 5000;
  const payload = {
    moveX: 0,
    moveZ: moving ? 1 : 0,
    yaw: looking ? (at - 3000) * 0.0005 : 0,
    pitch: 0,
    jumpHeld: false,
    sprintHeld: moving,
    flyToggle: frame === Math.round(7000 / frameMs),
  };
  baselineCharacters += encodeLogicEnvelope('player.input', frame, payload, sessionId).length;
  const emitted = gate.offer(payload, at);
  if (!emitted) continue;
  optimizedCharacters += encodeLogicEnvelope(
    'player.input',
    optimizedMessages,
    emitted,
    sessionId,
  ).length;
  optimizedMessages++;
  if (emitted.flyToggle) flyToggleDelivered++;
  if (previousDeliveredMoveZ === 0 && emitted.moveZ !== 0) movementStartsDelivered++;
  if (previousDeliveredMoveZ !== 0 && emitted.moveZ === 0) movementStopsDelivered++;
  previousDeliveredMoveZ = emitted.moveZ;
}

const messageReductionPercent = roundPercent(1 - optimizedMessages / sampleCount);
const characterReductionPercent = roundPercent(1 - optimizedCharacters / baselineCharacters);
const result = {
  fps,
  durationMs,
  sessionIdCharacters: sessionId.length,
  baselineMessages: sampleCount,
  optimizedMessages,
  messageReductionPercent,
  baselineCharacters,
  optimizedCharacters,
  characterReductionPercent,
  flyToggleDelivered,
  movementStartsDelivered,
  movementStopsDelivered,
  gate: gate.metrics,
};

console.log(`INPUT_TRANSPORT_BENCHMARK ${JSON.stringify(result)}`);
if (messageReductionPercent < 90 || characterReductionPercent < 90) {
  throw new Error('Input transport reduction must remain at least 90%.');
}
if (flyToggleDelivered !== 1 || movementStartsDelivered !== 1 || movementStopsDelivered !== 1) {
  throw new Error('Input transport gate lost a critical digital transition.');
}

function roundPercent(ratio) {
  return Math.round(ratio * 1000) / 10;
}
